INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('U.S. Visas & Immigration 101 for Startup Founders', 'San Francisco Startup Traction & Funding Network', 'Founders & Startups', 'Building a company in the U.S. is hard enough. Doing it as a non-citizen founder means navigating an immigration system that was never', 'Building a company in the U.S. is hard enough. Doing it as a non-citizen founder means navigating an immigration system that was never designed with startups in mind. This 101 session breaks down the essentials in plain English. You''ll get a clear map of the visa paths open to founders, how they differ, and what each one actually asks of you when you''re the one building the company. We''ll also look at how milestones like fundraising and revenue shape your options, and the mistakes that quietly More info: https://www.meetup.com/san-francisco-startup-traction-funding-network/events/316752969/', '2026-10-12T09:00:00-07:00', 'Online event', 'Online event', 'San Francisco', 'CA', '', 37.77, -122.41, 'San Francisco Startup Traction & Funding Network', 2, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/san-francisco-startup-traction-funding-network/events/316752969/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('From Dreamer to Doer: Build the Founder Mindset', 'San Francisco Startup Traction & Funding Network', 'Founders & Startups', 'Have you ever wondered why some people take the leap while others stay stuck? The difference isn''t luck, resources, or timing — it''s the', 'Have you ever wondered why some people take the leap while others stay stuck? The difference isn''t luck, resources, or timing — it''s the way founders think. Join Jonathan Greechan, Co-Founder & CEO of the Founder Institute, for a fascinating deep-dive into the psychology behind entrepreneurial action. In this live session, you''ll unpack the cognitive patterns that hold aspiring founders back and explore the mental frameworks that top entrepreneurs use to push through uncertainty. With practical More info: https://www.meetup.com/san-francisco-startup-traction-funding-network/events/316598541/', '2026-10-13T09:00:00-07:00', 'Online event', 'Online event', 'San Francisco', 'CA', '', 37.77, -122.41, 'San Francisco Startup Traction & Funding Network', 3, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/san-francisco-startup-traction-funding-network/events/316598541/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Building a Unicorn with AI Agents: From Idea to First Check', 'San Francisco Startup Traction & Funding Network', 'Founders & Startups', 'You have the idea. What you don''t have is the money to hire a team, and no investor will write a check until you show traction. **Join Adeo', 'You have the idea. What you don''t have is the money to hire a team, and no investor will write a check until you show traction. **Join Adeo Ressi, Chairman of the Founder Institute, to learn how solo founders run a squad of AI agents in place of their first five hires, what investors look for in AI-native companies in 2026, and how FI companies get funded, from Founder Capital''s $25K first checks to the FI Venture Network and local demo days.** **[Register now and bring your questions for More info: https://www.meetup.com/san-francisco-startup-traction-funding-network/events/316749002/', '2026-10-14T13:00:00-07:00', 'Online event', 'Online event', 'San Francisco', 'CA', '', 37.77, -122.41, 'San Francisco Startup Traction & Funding Network', 3, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/san-francisco-startup-traction-funding-network/events/316749002/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('How to Use AI to Position Your Startup to Buyers', 'San Francisco Startup Traction & Funding Network', 'Founders & Startups', 'You built the product. The market isn''t buying it yet. Usually the gap is positioning: buyers don''t see themselves in your pitch. **In this', 'You built the product. The market isn''t buying it yet. Usually the gap is positioning: buyers don''t see themselves in your pitch. **In this hands-on session, Jonathan Grover shows you how to use AI to fix that. You''ll build a synthetic version of your ideal buyer as an AI agent, then let it tear into your pitch in real time, surfacing the objections and gaps a real buyer would raise.** You''ll leave with sharper positioning that actually converts, plus a Claude skill you can take home and reuse More info: https://www.meetup.com/san-francisco-startup-traction-funding-network/events/316871402/', '2026-10-20T09:00:00-07:00', 'Online event', 'Online event', 'San Francisco', 'CA', '', 37.77, -122.41, 'San Francisco Startup Traction & Funding Network', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/san-francisco-startup-traction-funding-network/events/316871402/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
