INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('How We Got 256 Customers in 90 Days: The AI Sales Funnel, Step by Step [ONLINE]', 'Seattle AI for Business Owners', 'Women in Business', '**(PLEASE READ THE NOTE AT THE BOTTOM BEFORE YOU RSVP)** A step-by-step walkthrough of the AI sales funnel that brought in 256 paying', '**(PLEASE READ THE NOTE AT THE BOTTOM BEFORE YOU RSVP)** A step-by-step walkthrough of the AI sales funnel that brought in 256 paying customers in 90 days, built for solopreneurs and small business owners. The actual system, the actual numbers, and the AI tools behind each step. Most owners win clients the slow way: referrals, cold outreach and chasing leads who went quiet. That works until things get busy, and then new business stops. An automated funnel solves that. AI now drafts the pages, More info: https://www.meetup.com/seattle-ai-for-business-owners/events/316887209/', '2026-10-14T12:00:00-07:00', 'Online event', 'Online event', 'Seattle', 'WA', '', 47.61, -122.33, 'Seattle AI for Business Owners', 7, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/seattle-ai-for-business-owners/events/316887209/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Build Your Prompt Library with Claude: One Doc Your Whole Team Uses [ONLINE]', 'Seattle AI for Business Owners', 'Women in Business', 'In this session we''ll gather the prompts a team already relies on and turn them into one shared library of fill-in-the-blank templates,', 'In this session we''ll gather the prompts a team already relies on and turn them into one shared library of fill-in-the-blank templates, organised by task. Good prompts usually live scattered across chats and notes. Written down once, the best way to do a task is available to everyone. **What we''ll cover:** • Finding the prompts your team already relies on • Turning them into reusable templates with Claude, with blanks to fill in • Organizing one simple doc by task so anyone can find the right More info: https://www.meetup.com/seattle-ai-for-business-owners/events/316698020/', '2026-10-14T13:00:00-07:00', 'Online event', 'Online event', 'Seattle', 'WA', '', 47.61, -122.33, 'Seattle AI for Business Owners', 49, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/seattle-ai-for-business-owners/events/316698020/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Hire the Top 1% Remote Assistant: Find, Test and Train Them with Claude [ONLINE]', 'Seattle AI for Business Owners', 'Women in Business', 'In this session we''ll walk through how to find, test and hire a top 1% remote assistant who already knows how to use AI, and how Claude', 'In this session we''ll walk through how to find, test and hire a top 1% remote assistant who already knows how to use AI, and how Claude writes the job post, the test task and the training docs for you. Most owners hire their first assistant in a rush, pick the wrong person and end up doing the work twice. A clear role, a short paid test and written training change the outcome. **What we''ll cover:** • Which tasks to hand off first, and the one role that covers them • Where the best AI-savvy More info: https://www.meetup.com/seattle-ai-for-business-owners/events/316836728/', '2026-10-21T12:00:00-07:00', 'Online event', 'Online event', 'Seattle', 'WA', '', 47.61, -122.33, 'Seattle AI for Business Owners', 5, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/seattle-ai-for-business-owners/events/316836728/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('The One-Prompt Sales Page: Built with Claude in an Evening [ONLINE]', 'Seattle AI for Business Owners', 'Women in Business', 'In this session we''ll build a complete sales page with Claude from one well-written brief, section by section, and leave with a draft ready', 'In this session we''ll build a complete sales page with Claude from one well-written brief, section by section, and leave with a draft ready to publish. A sales page has a simple structure. With a clear brief, Claude drafts each part in your voice and you edit instead of starting from a blank page. **What we''ll cover:** • Writing the one brief that drives the whole page • Headline, promise, proof, offer and guarantee, in order • Editing out the generic AI phrases • Publishing the page this week More info: https://www.meetup.com/seattle-ai-for-business-owners/events/316860301/', '2026-10-23T12:00:00-07:00', 'Online event', 'Online event', 'Seattle', 'WA', '', 47.61, -122.33, 'Seattle AI for Business Owners', 4, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/seattle-ai-for-business-owners/events/316860301/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Startup Drinks', 'Seattle AI & SaaS Growth Community', 'Founders & Startups', '**This is a regular/monthly general startup event. Including this instance for our meet-up group because I''ll be there, and it''s a good', '**This is a regular/monthly general startup event. Including this instance for our meet-up group because I''ll be there, and it''s a good crowd and worth checking out.** You’ll find the group hanging around the far left side of the building on the inside. We usually try to take over the long table there. I will be there wearing a Seattle Seahawks cap and a [revturbine.com](http://revturbine.com/) t-shirt, so you can come and say hello! https://www.meetup.com/startupfriends/events/cjqpwtyjcpbfb More info: https://www.meetup.com/seattle-ai-saas-growth/events/315625143/', '2026-11-03T16:30:00-08:00', 'Fremont Brewing Company', '1050 North 34th Street', 'Seattle', 'WA', '', 47.68, -122.12, 'Seattle AI & SaaS Growth Community', 6, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/seattle-ai-saas-growth/events/315625143/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('What Founders Give Up and Gain', 'Seattle Angel', 'Founders & Startups', 'Understanding ownership, dilution, control, and alignment as startups raise outside capital. Explore how fundraising changes ownership,', 'Understanding ownership, dilution, control, and alignment as startups raise outside capital. Explore how fundraising changes ownership, governance, incentives, and decision-making inside growing companies. Learn how founders think about dilution, control, investor alignment, and financing structures while preparing for term sheet conversations, due diligence, and long-term company building. More info: https://www.meetup.com/seattle-angel/events/316720459/', '2026-10-15T10:00:00-07:00', 'Online event', 'Online event', 'Seattle', 'WA', '', 47.61, -122.33, 'Seattle Angel', 11, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/seattle-angel/events/316720459/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
