INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Unlock Tax Lien/Tax Deed Millionaire Secrets', 'Wealth Builders Network', 'Real Estate', 'Investing in real estate might sound like a dream, but the upfront costs and risks can be a nightmare. Forget the hassle of high-priced', 'Investing in real estate might sound like a dream, but the upfront costs and risks can be a nightmare. Forget the hassle of high-priced properties and mortgages. ➡️ **[Register here to learn more and attend a free class](https://premierwealthbuilders.com/liens)**[. ](https://premierwealthbuilders.com/liens) There''s a smarter, low-cost, and often **safer way** to step into the real estate game: **tax liens** and **tax deeds**. **Tax Lien Advantage**: Invest in unpaid property taxes and earn More info: https://www.meetup.com/seattle-real-estate-investor-community/events/316877507/', '2026-10-12T18:00:00-07:00', 'Online event', 'Online event', 'Seattle', 'WA', '', 47.61, -122.33, 'Wealth Builders Network', 2, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/seattle-real-estate-investor-community/events/316877507/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('[Virtual] Simple Real Estate Strategies That Work (Fun, Free, & Gets You Paid!)', 'Wealth Builders Network', 'Real Estate', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks of prep just to get started (or worst of all, they just want to sell you their expensive course or coaching). **We decided to do the exact opposite**—and hundreds of agents now agree. Join us **LIVE (virtual) every Wednesday at 9:00 AM CST** for a zero-fluff, action-packed call where active, top-producing agents openly share exactly what’s working right More info: https://www.meetup.com/seattle-real-estate-investor-community/events/316694296/', '2026-10-14T07:00:00-07:00', 'Online event', 'Online event', 'Seattle', 'WA', '', 47.61, -122.33, 'Wealth Builders Network', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/seattle-real-estate-investor-community/events/316694296/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
