INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('IN-PERSON EVENT: How to Buy Investment Property with Rates as Low as 3.75%*', 'Real Estate Investing- Free Education & Mentoring (SF)', 'Real Estate', 'Real estate investing in 2026 looks very different than it did just a few years ago. In many markets, interest rates remain elevated,', 'Real estate investing in 2026 looks very different than it did just a few years ago. In many markets, interest rates remain elevated, inventory dynamics are shifting, and insurance costs are rising in certain areas. As a result, many investors are asking: **Is it still possible to achieve strong returns in today’s market? The answer is YES**—but only if you understand where the opportunities have moved and how to structure deals correctly. You’ll hear directly from Scott Pastel, Vice President More info: https://www.meetup.com/sf-real-estate-investing-free-education-and-mentoring/events/316771306/', '2026-10-13T18:00:00-07:00', 'Sonesta Select San Jose Airport', '1727 Technology Dr, San Jose, CA 95110, USA', 'San Jose', 'CA', '95110', 37.365338097918, -121.917161733624, 'Real Estate Investing- Free Education & Mentoring (SF)', 1, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/sf-real-estate-investing-free-education-and-mentoring/events/316771306/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
