INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Preparing to Sell Your Business', 'SFLO-Entrepreneurs by Broward SCORE', 'Founders & Startups', 'Selling a business is one of the most significant financial and personal decisions an owner will ever make. The most successful exits are', 'Selling a business is one of the most significant financial and personal decisions an owner will ever make. The most successful exits are rarely the result of timing alone. They are the result of thoughtful planning well before a company ever goes to market. Whether your goal is to retire, pursue a new venture, or capitalize on years of hard work, preparing early can dramatically increase your company’s value, attract stronger buyers, and create a smoother transaction. In this practical and More info: https://www.meetup.com/sflo-entrepreneurs/events/316423623/', '2026-10-13T18:00:00-04:00', 'Online event', 'Online event', 'Fort Lauderdale', 'FL', '', 26.12, -80.13, 'SFLO-Entrepreneurs by Broward SCORE', 2, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/sflo-entrepreneurs/events/316423623/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Small Business Financial Statements', 'SFLO-Entrepreneurs by Broward SCORE', 'Founders & Startups', 'In this workshop, business owners will learn the three most important financial documents: balance sheets, profit and loss statements, and', 'In this workshop, business owners will learn the three most important financial documents: balance sheets, profit and loss statements, and cash flow reports. At the end of the workshop, business owners will be able to prepare or work with a professional to prepare these documents for their businesses. A good banking relationship belongs in your business toolbox! Learn more about the modern banking services that can empower your business! Fee: Free Copy of the recording and materials will be More info: https://www.meetup.com/sflo-entrepreneurs/events/316423678/', '2026-10-14T18:00:00-04:00', 'Online event', 'Online event', 'Fort Lauderdale', 'FL', '', 26.12, -80.13, 'SFLO-Entrepreneurs by Broward SCORE', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/sflo-entrepreneurs/events/316423678/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('SF Mature Women in Tech Monthly Meeting - Hiring with AI', 'Mature Women in Tech Meetup', 'Women in Business', 'Join us for an evening of networking with other women in technology and technology-adjacent fields. Jane Sherman, one of our organizers,', 'Join us for an evening of networking with other women in technology and technology-adjacent fields. Jane Sherman, one of our organizers, will continue last month’s conversation about hiring in the age of AI. She’ll share the story of a recent hiring process, including how she used AI to evaluate candidates, what worked, what went wrong, and what she learned along the way. This isn’t a “how to hire with AI” presentation or a claim to expertise. It’s one person’s experience—and a starting point More info: https://www.meetup.com/sfmaturewomenintech/events/314875120/', '2026-10-15T19:00:00-07:00', 'Online event', 'Online event', 'San Francisco', 'CA', '', 37.78, -122.42, 'Mature Women in Tech Meetup', 70, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/sfmaturewomenintech/events/314875120/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
