INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('SFTech4Good Happy Hour: End of Day Networking and Cocktails', 'SFTech4Good', 'Founders & Startups', 'It’s time! I’m still looking for sustainable work, so events are few and far between until I have a stable income again. With that said,', 'It’s time! I’m still looking for sustainable work, so events are few and far between until I have a stable income again. With that said, let’s meet up for a drink. That’s easy and straightforward. People can catch up and network! * If you can’t make it but have ideas, write me. * If you want to build and host an event but can’t make it, write me. * If you want to have a drink, relax, and can make it, show up. My long-term goal is to bring back events at least quarterly. As always, they''ll be More info: https://www.meetup.com/sftech4good/events/316562819/', '2026-10-14T17:00:00-07:00', 'Dawn Club', '10 Annie St, San Francisco, CA 94103, USA', 'San Francisco', 'CA', '94105', 37.787939735823, -122.402799901267, 'SFTech4Good', 1, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/sftech4good/events/316562819/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('SF Tech Mixer 2026', 'San Francisco Startups & Tech Mixer', 'Women in Business', 'JOIN US FOR THE BEST NETWORKING EVENT IN SAN FRANCISCO! **As seen in Entrepreneur Magazine.** THIS IS A PAID EVENT RSVP HERE ••>', 'JOIN US FOR THE BEST NETWORKING EVENT IN SAN FRANCISCO! **As seen in Entrepreneur Magazine.** THIS IS A PAID EVENT RSVP HERE ••> https://tinyurl.com/mrx9m8vn https://tinyurl.com/mrx9m8vn https://tinyurl.com/mrx9m8vn https://tinyurl.com/mrx9m8vn https://tinyurl.com/mrx9m8vn https://tinyurl.com/mrx9m8vn https://tinyurl.com/mrx9m8vn https://tinyurl.com/mrx9m8vn https://tinyurl.com/mrx9m8vn https://tinyurl.com/mrx9m8vn <•• PROUDLY SPONSORED BY: connect in tech NO REFUNDS OR EXCHANGES. ***Event Date More info: https://www.meetup.com/sftechmixer/events/316420463/', '2026-10-29T18:00:00-07:00', 'Asiento', '2730 21st St', 'San Francisco', 'CA', '', 37.78, -122.42, 'San Francisco Startups & Tech Mixer', 9, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/sftechmixer/events/316420463/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
